#include "model_mesh.h"
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <float.h>
typedef struct {const unsigned char*p;size_t n;} View;
struct NFPCModelMesh{unsigned width,height,sv,sf,tv,indexed,clip[4],order;size_t used,capacity;float*vertices;double*camera;unsigned char*rgba,*indices;};
static uint32_t u32(const void*p,size_t at){uint32_t v;memcpy(&v,(const unsigned char*)p+at,4);return v;}
static uint16_t u16(const void*p,size_t at){uint16_t v;memcpy(&v,(const unsigned char*)p+at,2);return v;}
static double d64(const void*p,size_t at){double v;memcpy(&v,(const unsigned char*)p+at,8);return v;}
static int section(const NFPCSourceFrame*f,unsigned owner,unsigned index,View*out){const void*ptr;size_t n;if(index>=5||!nf_pc_source_frame_component(f,owner,NFPC_GEOMETRY,&ptr,&n)||n<92)return 0;size_t at=u32(ptr,36+12*index),size=u32(ptr,40+12*index);if(at>n||size>n-at)return 0;out->p=(const unsigned char*)ptr+at;out->n=size;return 1;}
static unsigned models(View b){if(b.n<8)return 0;if(u32(b.p,0)==0x324d464e)return 1;if(u32(b.p,0)!=0x314c4d4e)return 0;unsigned count=u32(b.p,4);if(count<2||count>16||b.n<8+count*8)return 0;size_t end=8+count*8;for(unsigned i=0;i<count;i++){size_t at=u32(b.p,8+i*8),n=u32(b.p,12+i*8);if(at%8||at<end||at>b.n||n<160||n>b.n-at)return 0;end=at+n;}return end==b.n?count:0;}
unsigned nf_pc_source_model_count(const NFPCSourceFrame*f,unsigned owner){View b;return section(f,owner,0,&b)?models(b):0;}
static int pose(const unsigned char*p,size_t at,double out[7]){for(unsigned i=0;i<7;i++){out[i]=d64(p,at+i*8);if(!isfinite(out[i]))return 0;}double n=sqrt(out[3]*out[3]+out[4]*out[4]+out[5]*out[5]+out[6]*out[6]);if(!isfinite(n)||n<1e-10)return 0;for(unsigned i=3;i<7;i++)out[i]/=n;return 1;}
static void rotate(const double q[7],double v[3]){double tx=2*(q[4]*v[2]-q[5]*v[1]),ty=2*(q[5]*v[0]-q[3]*v[2]),tz=2*(q[3]*v[1]-q[4]*v[0]);double out[3]={v[0]+q[6]*tx+q[4]*tz-q[5]*ty,v[1]+q[6]*ty+q[5]*tx-q[3]*tz,v[2]+q[6]*tz+q[3]*ty-q[4]*tx};memcpy(v,out,sizeof(out));}
NFPCModelMesh* nf_pc_model_mesh_decode(const void*data,size_t n,size_t maximum){if(!data||n<160||n>64u*1024*1024||maximum>32u*1024*1024||maximum<sizeof(NFPCModelMesh))return NULL;const unsigned char*p=data;if(u32(p,0)!=0x324d464e)return NULL;unsigned sv=u32(p,4),sf=u32(p,8),corners=u32(p,12),w=u32(p,16),h=u32(p,20);if(!sv||sv>2048||!sf||sf>512||!corners||corners>4096||!w||w>1024||!h||h>1024)return NULL;size_t pixels=(size_t)w*h,base=160+sv*24+sf+corners*18+pixels*4;if(base>n)return NULL;int indexed=n!=base;if(indexed&&(n-base!=16+pixels||u32(p,base)!=0x31495a4e||u32(p,base+4)!=w||u32(p,base+8)!=h||u32(p,base+12)))return NULL;double cx=d64(p,24),cy=d64(p,32),scale=d64(p,40),cam[7],object[7];if(!isfinite(cx)||!isfinite(cy)||!isfinite(scale)||scale<=0||!pose(p,48,cam)||!pose(p,104,object))return NULL;size_t floats=(size_t)sf*62*3*5,used=sizeof(NFPCModelMesh)+sv*3*sizeof(double)+floats*sizeof(float)+pixels*4+(indexed?pixels:0);if(used>maximum)return NULL;NFPCModelMesh*m=calloc(1,sizeof(*m));if(!m)return NULL;m->width=w;m->height=h;m->sv=sv;m->sf=sf;m->indexed=indexed;m->used=used;m->capacity=floats;m->clip[1]=240;m->clip[3]=160;m->order=UINT32_MAX;m->camera=malloc(sv*3*sizeof(double));m->vertices=malloc(floats*sizeof(float));m->rgba=malloc(pixels*4);if(indexed)m->indices=malloc(pixels);if(!m->camera||!m->vertices||!m->rgba||(indexed&&!m->indices))goto fail;
 for(unsigned i=0;i<sv;i++){double v[3];for(unsigned j=0;j<3;j++){v[j]=d64(p,160+i*24+j*8);if(!isfinite(v[j]))goto fail;}rotate(object,v);for(unsigned j=0;j<3;j++)v[j]+=object[j]-cam[j];rotate(cam,v);for(unsigned j=0;j<3;j++){if(!isfinite(v[j]))goto fail;m->camera[i*3+j]=v[j];}}
 size_t sizes=160+sv*24,ids=sizes+sf,uv=ids+corners*2,texture=uv+corners*16;unsigned total=0;for(unsigned i=0;i<sf;i++){unsigned count=p[sizes+i];if(count<3||count>32)goto fail;total+=count;}if(total!=corners)goto fail;for(unsigned i=0;i<corners;i++)if(u16(p,ids+i*2)>=sv||!isfinite(d64(p,uv+i*16))||!isfinite(d64(p,uv+i*16+8)))goto fail;
 unsigned corner=0;size_t output=0;for(unsigned face=0;face<sf;face++){unsigned count=p[sizes+face];double ring[32][5],clipped[64][5],projected[64][5];for(unsigned i=0;i<count;i++){unsigned id=u16(p,ids+(corner+i)*2);for(unsigned j=0;j<3;j++)ring[i][j]=m->camera[id*3+j];ring[i][3]=d64(p,uv+(corner+i)*16);ring[i][4]=d64(p,uv+(corner+i)*16+8);}corner+=count;unsigned visible=0;for(unsigned i=0;i<count;i++){double*a=ring[(i+count-1)%count],*v=ring[i];int ai=a[2]>=1,bi=v[2]>=1;if(ai!=bi){double t=(1-a[2])/(v[2]-a[2]);for(unsigned j=0;j<5;j++)clipped[visible][j]=a[j]+(v[j]-a[j])*t;clipped[visible++][2]=1;}if(bi)memcpy(clipped[visible++],v,5*sizeof(double));}if(visible<3)continue;double area=0;for(unsigned i=0;i<visible;i++){double*v=clipped[i],q=1/v[2];projected[i][0]=cx+scale*v[0]*q;projected[i][1]=cy+scale*v[1]*q;projected[i][2]=v[3]*q;projected[i][3]=v[4]*q;projected[i][4]=q;}for(unsigned i=0;i<visible;i++)area+=projected[i][0]*projected[(i+1)%visible][1]-projected[(i+1)%visible][0]*projected[i][1];if(!isfinite(area))goto fail;if(area>=0)continue;for(unsigned i=1;i<visible-1;i++){unsigned triangle[3]={0,i,i+1};for(unsigned j=0;j<3;j++)for(unsigned k=0;k<5;k++){double value=projected[triangle[j]][k];if(!isfinite(value)||fabs(value)>FLT_MAX||output>=floats)goto fail;m->vertices[output++]=(float)value;}}}
 m->tv=(unsigned)(output/5);memcpy(m->rgba,p+texture,pixels*4);if(indexed)memcpy(m->indices,p+base+16,pixels);return m;
fail:nf_pc_model_mesh_free(m);return NULL;}
static int layout(const NFPCSourceFrame*f,unsigned owner,unsigned model,unsigned count,unsigned clip[4],unsigned*order_index){View world,id,order;if(!section(f,owner,1,&world)||world.n<8||u32(world.p,0)!=0x31444652||u32(world.p,4)>128||!section(f,owner,4,&id)||!section(f,owner,2,&order))return 0;unsigned surfaces=u32(world.p,4),entries=surfaces+count;size_t base=8+entries*20;if(id.n<base||u32(id.p,0)!=0x3149464e||u32(id.p,4)!=entries||order.n!=8+entries*4||u32(order.p,0)!=0x314f464e||u32(order.p,4)!=entries)return 0;unsigned char seen[144]={0};*order_index=UINT32_MAX;for(unsigned i=0;i<entries;i++){uint32_t value=u32(order.p,8+i*4);unsigned is_model=value>=0xfffffff0u,index=is_model?UINT32_MAX-value:value;if(index>=(is_model?count:surfaces))return 0;unsigned slot=index+(is_model?surfaces:0);if(seen[slot])return 0;seen[slot]=1;if(is_model&&index==model)*order_index=i;}if(*order_index==UINT32_MAX)return 0;clip[0]=clip[2]=0;clip[1]=240;clip[3]=160;if(id.n==base)return 1;if(id.n-base<16)return 0;uint32_t magic=u32(id.p,base),n=u32(id.p,base+4);double alpha=d64(id.p,base+8);if(!((magic==0x3142464e&&n==surfaces)||(magic==0x3242464e&&n==entries))||id.n!=base+16+n*8||!isfinite(alpha)||alpha<0||alpha>=1)return 0;for(unsigned i=0;i<n;i++){unsigned a=u16(id.p,base+16+i*8),b=u16(id.p,base+18+i*8),c=u16(id.p,base+20+i*8),d=u16(id.p,base+22+i*8);if(a>b||b>240||c>d||d>160)return 0;}if(magic==0x3242464e)for(unsigned j=0;j<4;j++)clip[j]=u16(id.p,base+16+(surfaces+model)*8+j*2);return 1;}
NFPCModelMesh* nf_pc_source_model_mesh(const NFPCSourceFrame*f,unsigned owner,unsigned model,size_t maximum){View b;if(!section(f,owner,0,&b))return NULL;unsigned count=models(b),clip[4],order;if(!count||model>=count||!layout(f,owner,model,count,clip,&order))return NULL;if(count>1){size_t at=u32(b.p,8+model*8),n=u32(b.p,12+model*8);b.p+=at;b.n=n;}NFPCModelMesh*m=nf_pc_model_mesh_decode(b.p,b.n,maximum);if(m){memcpy(m->clip,clip,sizeof(clip));m->order=order;}return m;}
void nf_pc_model_mesh_free(NFPCModelMesh*m){if(!m)return;free(m->camera);free(m->vertices);free(m->rgba);free(m->indices);free(m);}
int nf_pc_model_mesh_info(const NFPCModelMesh*m,uint64_t out[12]){if(!m||!out)return 0;uint64_t v[12]={m->width,m->height,m->sv,m->sf,m->tv,m->indexed,m->used,m->clip[0],m->clip[1],m->clip[2],m->clip[3],m->order};memcpy(out,v,sizeof(v));return 1;}
int nf_pc_model_mesh_buffer(const NFPCModelMesh*m,unsigned kind,const void**p,size_t*n){if(!m||kind>3||!p||!n)return 0;const void*ptr[4]={m->vertices,m->camera,m->rgba,m->indices};size_t bytes[4]={(size_t)m->tv*5*sizeof(float),(size_t)m->sv*3*sizeof(double),(size_t)m->width*m->height*4,m->indexed?(size_t)m->width*m->height:0};*p=ptr[kind];*n=bytes[kind];return 1;}
int nf_pc_model_mesh_plane(const NFPCModelMesh*m,unsigned triangle,float out[11]){if(!m||!out||triangle>=m->tv/3)return 0;const float*v=m->vertices+triangle*15;double x=v[0],y=v[1],bx=v[5]-x,by=v[6]-y,cx=v[10]-x,cy=v[11]-y,det=bx*cy-by*cx,normal=v[4];if(!isfinite(det)||det==0||!(normal>0))return 0;float plane[11];plane[0]=(float)x;plane[1]=(float)y;for(unsigned c=0;c<3;c++){double a=v[2+c],b=v[7+c]-a,d=v[12+c]-a;plane[2+c]=(float)(a/normal);plane[5+c]=(float)((b*cy-d*by)/(det*normal));plane[8+c]=(float)((bx*d-cx*b)/(det*normal));if(!isfinite(plane[2+c])||!isfinite(plane[5+c])||!isfinite(plane[8+c]))return 0;}memcpy(out,plane,sizeof(plane));return 1;}
